/* Original generated-art crops. No printed rules or full mockup layouts are used. */
window.RMExpandedArtImages={"wood":"data:image/webp;base64,","civic":"data:image/webp;base64,","robot0":"data:image/webp;base64,","robot1":"data:image/webp;base64,","robot2":"data:image/webp;base64,","robot3":"data:image/webp;base64,","robot4":"data:image/webp;base64,","city":"data:image/webp;base64,","artifact0":"data:image/webp;base64,","artifact1":"data:image/webp;base64,","artifact2":"data:image/webp;base64,","portrait":"data:image/webp;base64,","ancient0":"data:image/webp;base64,","ancient1":"data:image/webp;base64,","ancient2":"data:image/webp;base64,","ancient3":"data:image/webp;base64,","ancient4":"data:image/webp;base64,"};
/* The visual layer never owns game rules. Board geometry is redrawn, not pasted from a generated screenshot. */
(()=>{'use strict';const A=window.RMExpandedArtImages;
const make=(tag,cls,txt)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(txt!==undefined)e.textContent=txt;return e};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const colors=['#f1c63a','#be4b43','#3c80b5','#65a54c','#9562b0'];
const phaseCols=['#ca4652','#367abb','#9559b6','#ed903d','#69a450'];
const partyCols=['#d9b73a','#474a4c','#65a34b','#c94743','#9359a9'];
const phaseLabels=['업그레이드','조립','설계','제작','재활용'];
const phaseSymbols=['⇧','✣','△','⚙','♻'];
const symbols=['●','⚔','♜','❧','✦'];
const hash=s=>[...String(s)].reduce((n,c)=>(n*31+c.codePointAt(0))>>>0,0);
const svg=(body,w,h)=>`<svg class="rm-redrawn" viewBox="0 0 ${w} ${h}" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">${body}</svg>`;
const rect=(x,y,w,h,fill,extra='')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="2" fill="${fill}" ${extra}/>`;
const text=(x,y,t,sz=11,fill='#26372e',anchor='middle')=>`<text x="${x}" y="${y}" text-anchor="${anchor}" font-size="${sz}" fill="${fill}" font-weight="700" font-family="system-ui,sans-serif">${esc(t)}</text>`;
const line=(x,y,x2,y2,stroke='#504b42',sw=1)=>`<path d="M${x},${y} L${x2},${y2}" stroke="${stroke}" stroke-width="${sw}"/>`;
const circle=(x,y,r,fill,stroke='#6f5e43')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${fill}" stroke="${stroke}"/>`;
const pic=(key,x,y,w,h)=>`<image href="${A[key]}" x="${x}" y="${y}" width="${w}" height="${h}" preserveAspectRatio="xMidYMid slice"/>`;
function sector(cx,cy,r1,r2,a,b,fill){const pt=(r,t)=>[cx+r*Math.cos(t*Math.PI/180),cy+r*Math.sin(t*Math.PI/180)].map(x=>x.toFixed(2)).join(',');return `<path d="M${pt(r1,a)} L${pt(r2,a)} A${r2},${r2} 0 0 1 ${pt(r2,b)} L${pt(r1,b)} A${r1},${r1} 0 0 0 ${pt(r1,a)} Z" fill="${fill}" stroke="#7f786c" stroke-width=".65"/>`;}
function region(index=0){let s=rect(1,1,178,178,'#e9e4d9','stroke="#817b6b"');const cx=174,cy=174;
 for(let j=0;j<5;j++){let a=181+j*17.5,b=a+17;for(let k=0;k<5;k++)s+=sector(cx,cy,32+k*11,43+k*11,a,b,partyCols[j]);for(let k=0;k<5;k++)s+=sector(cx,cy,91+k*9,100+k*9,a,b,'#fcfbf6');}
 s+=rect(11,9,34,23,'#d7d4c9','stroke="#a9a396"');s+=text(28,24,'지역',9);for(let i=0;i<4;i++)s+=rect(48+i*30,9,26,23,'#d4d1c7','stroke="#aaa69a"');for(let i=0;i<5;i++)s+=circle(13,48+i*17,5,'#c6c1b6');s+=rect(153,151,22,22,'#c5b8a4');s+=text(165,165,'투표',7);return svg(`<g transform="rotate(${index*90} 90 90)">${s}</g>`,180,180);}
function partyProgram(){let s=rect(1,1,226,72,'#e9dfd0','stroke="#8c8476"');for(let i=0;i<5;i++){s+=rect(6+i*44,8,39,54,'#f2efe4','stroke="#7c7d74"');s+=rect(9+i*44,12,33,9,'#6e847a');s+=text(25+i*44,38,['§','✚','⌘','☀','↔'][i],15);s+=rect(9+i*44,44,33,14,'#e1dac7');}return svg(s,228,74);}
function robotBoard(){let s=rect(0,0,330,185,'#4d5153','stroke="#333"');s+=rect(8,8,314,28,'#f5f6f0');s+=text(17,25,'보관 / 자원',9,'#555','start');for(let i=0;i<9;i++){s+=rect(89+i*25,12,23,19,'#fff','stroke="#838b88"');s+=text(100+i*25,25,i,8);}for(let j=0;j<3;j++){const col=phaseCols[j+2],y=40+j*46;s+=rect(8,y,65,43,col);s+=text(40,y+13,phaseLabels[j+2],9,'white');s+=text(40,y+30,phaseSymbols[j+2],15,'white');for(let k=0;k<6;k++){s+=rect(77+k*40,y,37,43,col);s+=rect(81+k*40,y+4,29,35,'#ffffffa0','stroke="#ffffff"');s+=text(95+k*40,y+24,phaseSymbols[j+2],11,col);}}
 s+=rect(8,160,65,20,'#4195a0');s+=text(40,174,'발명가',8,'white');return svg(s,330,185);}
function robotCentral(){let s=rect(1,1,399,98,'#3e4447','stroke="#181e21"');for(let i=0;i<8;i++){const x=18+i*46+(i>=4?12:0);s+=rect(x,7,32,21,'#faf9ee');s+=text(x+16,22,i+1,12);if(!i)s+=circle(x+16,17,6,'#b83d37');}for(let i=0;i<5;i++){let x=9+i*78;s+=rect(x,34,74,57,phaseCols[i]);s+=rect(x+4,38,66,49,'#ffffffc8');s+=text(x+37,53,phaseLabels[i],10);s+=text(x+37,76,phaseSymbols[i],23,phaseCols[i]);}return svg(s,401,100);}
function hadaraBoard(){let s=rect(1,1,336,152,'#c1a477','stroke="#826743"');for(let i=0;i<4;i++){s+=rect(72+i*54,5,50,28,'#eee1bb','stroke="#8a7656"');s+=circle(97+i*54,19,11,i<2?'#c7d1d5':'#c9b789');}s+=rect(5,38,91,108,'#b6d1df','stroke="#718b98"');for(let i=0;i<4;i++){let x=8+i%2*43,y=42+Math.floor(i/2)*49;s+=rect(x,y,40,45,'#d9e8ee','stroke="#6b8fa6"');s+=text(x+20,y+15,'조각상',7);s+=rect(x+10,y+20,20,20,'#f6f0df','stroke="#8aa1a4"');}for(let j=0;j<4;j++){let y=40+j*26;s+=rect(101,y,30,23,colors[j]);s+=text(116,y+15,symbols[j],11);for(let k=0;k<10;k++){let x=135+k*19;s+=rect(x,y,18,23,colors[j],'stroke="#fff8df"');s+=text(x+9,y+15,k+1,9,'#fff');}}s+=rect(291,5,39,28,'#6b6254');s+=text(310,24,'✦',16,'white');return svg(s,338,154);}
function hadaraWheel(){const cx=150,cy=150;let s='';const pt=(r,t)=>[cx+r*Math.cos(t*Math.PI/180),cy+r*Math.sin(t*Math.PI/180)].join(',');const outer=Array.from({length:5},(_,i)=>pt(146,-126+i*72)).join(' ');s+=`<polygon points="${outer}" fill="#287181" stroke="#514c3a" stroke-width="3"/>`;for(let i=0;i<5;i++){let a=-90+i*72;let a1=a-36,a2=a+36;s+=`<path d="M${cx},${cy} L${pt(144,a1)} L${pt(144,a2)} Z" fill="${colors[i]}" fill-opacity=".7" stroke="#337785" stroke-width="3"/>`;let ang=a*Math.PI/180,x=cx+101*Math.cos(ang),y=cy+101*Math.sin(ang);s+=`<g transform="translate(${x} ${y}) rotate(${a+90})">${rect(-23,-30,46,60,'#ded4b4','stroke="#8e7959"')}${rect(-20,-27,40,54,colors[i],'stroke="#f9f0da"')}${text(0,5,symbols[i],16,'white')}</g>`;}s+=circle(cx,cy,35,'#5a574d','#d6c49b');for(let i=0;i<5;i++){let a=(-90+i*72)*Math.PI/180;s+=circle(cx+23*Math.cos(a),cy+23*Math.sin(a),7,'#9a8e75','#eadcc2');s+=text(cx+23*Math.cos(a),cy+3+23*Math.sin(a),symbols[i],8,'#fff');}s+=circle(cx,cy,6,'#dbcfac');return svg(s,300,300);}
function cityBoard(){let s=rect(0,0,420,224,'#3c4e58','stroke="#303d48"');s+=pic('city',0,0,420,110);s+=rect(0,0,420,48,'#d8e4d5','opacity=".72"');s+=text(62,12,'사기 / 지식',9);for(let j=0;j<2;j++)for(let i=0;i<6;i++){s+=rect(6+i*17,16+j*13,16,12,'#f8ebd8','stroke="#b9b3a0"');s+=text(14+i*17,25+j*13,i+1,7);}s+=rect(127,6,285,40,'#b5d39e','opacity=".84"');s+=text(270,19,'이카루스 · 행복',10);for(let i=0;i<4;i++)s+=rect(152+i*62,24,54,17,'#edead7','stroke="#738d73"');for(let j=0;j<3;j++){const x=6+j*139,y=53;const c=['#b95a45','#a97d3c','#3d93b8'][j];s+=rect(x,y,132,110,c,'opacity=".92"');s+=text(x+66,y+13,['유포리아','황무지','지하'][j],10,'white');s+=text(x+66,y+25,['에너지 / 금','식량 / 점토','물 / 돌'][j],8,'white');for(let k=0;k<2;k++){s+=rect(x+7+k*38,y+31,34,32,'#6a92bd','stroke="#dfedf5"');s+=line(x+10+k*38,y+36,x+37+k*38,y+59,'#c9e3f4',1);s+=line(x+10+k*38,y+59,x+37+k*38,y+36,'#c9e3f4',1);}for(let k=0;k<5;k++)s+=rect(x+89,y+31+k*12,32,10,'#e5ded0','stroke="#7f786b"');s+=text(x+60,y+78,'터널',8,'white');for(let k=0;k<5;k++)s+=rect(x+8+k*23,y+85,21,17,'#bdada2','stroke="#eee0d3"');s+=rect(x+8,y+85,21,17,'#d382ad');}s+=rect(213,169,202,50,'#d4cfb9');for(let i=0;i<4;i++){s+=rect(220,173+i*11,190,9,['#c86d56','#d4ad69','#609fba','#8bb977'][i]);}s+=text(316,215,'충성도',8);s+=text(102,198,'공용 행동 구역',10,'#f7eed9');return svg(s,420,224);}
const boardDraw=(key,index)=>({region:()=>region(index),party:partyProgram,robotMat:robotBoard,robotCentral,hadaraMat:hadaraBoard,hadaraWheel,city:cityBoard}[key]?.());
function renderBoard(face,key,index){face.classList.add('rm-board-face','rm-'+key);face.innerHTML=boardDraw(key,index);}
function decorate(b,p,id){b.dataset.rmArtGame=id;const f=b.querySelector('.face');if(!f)return;const n=p.name||'',v=String(p.value??''),pid=p.id||'';const h=hash(pid+n);let key='';
 if(id==='die-macher'&&p.type==='tile'&&/^(지역판|지역 [1-4])/.test(n))key='region';
 if(id==='die-macher'&&p.type==='tile'&&/정당판|정당 프로그램/.test(n))key='party';
 if(id==='raging-robots'&&p.type==='tile'&&n==='개인판')key='robotMat';
 if(id==='raging-robots'&&p.type==='tile'&&n==='중앙판')key='robotCentral';
 if(id==='hadara'&&p.type==='tile'&&n==='개인판')key='hadaraMat';
 if(id==='hadara'&&p.type==='wheel')key='hadaraWheel';
 if(id==='euphoria'&&p.type==='tile'&&n==='공용판')key='city';
 if(key){renderBoard(f,key,key==='region'?Number(pid.match(/\d+$/)?.[0]||0)%4:0);b.dataset.rmBoard=key;return;}
 if(p.type==='card'||p.type==='robot'){
 let art=id==='raging-robots'&&p.type==='robot'?'robot'+(h%5):id==='hadara'?'ancient'+(h%5):id==='euphoria'?(/유물/.test(n)?'artifact'+(h%3):'portrait'):id==='die-macher'&&/지역|정치인|여론조사/.test(n)?'civic':'';
 f.classList.add('rm-printed-card');f.replaceChildren(make('b','rm-card-title',n));if(art){const im=make('img','rm-card-art');im.src=A[art];im.alt='';f.append(im);b.dataset.rmGeneratedArt=art;}else{const icon=make('span','rm-card-emblem',id==='die-macher'?(/찬성|일치/.test(v)?'✓':/반대/.test(v)?'×':'§'):id==='raging-robots'?'⚙':'◆');f.append(icon);}f.append(make('span','rm-card-rule',v));
 }else if(p.type==='back'){f.classList.add('rm-printed-back');f.replaceChildren(make('span','rm-back-border'),make('span','rm-back-emblem',id==='die-macher'?(/정책/.test(n)?'§':/여론/.test(n)?'✓':'▧'):id==='raging-robots'?(/에너지/.test(n)?'ϟ':/수업/.test(n)?'✎':/발명/.test(n)?'♟':'⚙'):id==='hadara'?symbols[Math.max(0,['수입','군사','문화','식량','특수'].findIndex(x=>n.includes(x)))]:/시장/.test(n)?'◇':'◈'));
 }else if(p.type==='cube'&&id==='euphoria'){const kind={'금':'gold','돌':'stone','점토':'clay','에너지':'energy','물':'water','식량':'food','행복':'bliss'}[n];if(kind){b.dataset.rmResource=kind;f.classList.add('rm-commodity');}}
 else if(p.type==='cube'&&id==='die-macher'&&n.includes('언론'))f.classList.add('rm-octagon');
 else if(p.type==='marker'&&id==='die-macher')f.classList.add('rm-octagon');
 else if(id==='die-macher'&&p.type==='bill'){f.classList.add('rm-banknote');f.style.backgroundImage=`linear-gradient(90deg,#e2d4b2cc,#f3eedacc),url('${A.civic}')`;b.dataset.rmGeneratedArt='civic';}
 else if(p.type==='tile'&&id==='hadara'&&/군사|식민지/.test(n)&&/식민지|개/.test(v)){f.classList.add('rm-colony');f.style.backgroundImage=`linear-gradient(#fff0 20%,#f7ecd6 72%),url('${A['ancient'+h%5]}')`;b.dataset.rmGeneratedArt='ancient'+h%5;}
 else if(p.type==='tile'&&id==='euphoria'&&/시장/.test(n)){f.classList.add('rm-market');}
 else if(p.type==='tile'&&id==='hadara'&&/금메달/.test(n)){f.classList.add('rm-medal');}
}
function insertCentral(g,key,children){const wrap=make('div','rm-central-layout rm-layout-'+key);const visual=make('div','rm-board-graphic');visual.innerHTML=boardDraw(key,0);wrap.append(visual);const row=make('div','rm-board-items');children.forEach(c=>row.append(c));wrap.append(row);g.prepend(wrap);}
function arrange(g,zone,id,overview){const children=[...g.children].filter(c=>c.classList.contains('piece'));
 if(id==='euphoria'&&overview){const stars=children.filter(c=>c.classList.contains('star'));if(stars.length){const bank=make('div','rm-star-bank');g.insertBefore(bank,stars[0]);stars.forEach(c=>bank.append(c));bank.append(make('span','rm-star-label','권위 별 '+stars.length+'개'));}}
 if(id==='die-macher'){
 const regions=children.filter(c=>c.dataset.rmBoard==='region');if(regions.length===4){const group=make('div','rm-region-group');regions.forEach(c=>group.append(c));g.prepend(group);}
 }
 if(id==='raging-robots'&&/중앙판|공용 구성품/.test(zone.name)){const phases=children.filter(c=>phaseLabels.some(n=>c.getAttribute('aria-label')?.startsWith(n+' '))&&c.classList.contains('tile'));if(phases.length===5){const round=children.find(c=>c.getAttribute('aria-label')?.startsWith('라운드 '));insertCentral(g,'robotCentral',round?[round,...phases]:phases);}}
 if(id==='hadara'&&/시대 I 배치|공용 구성품/.test(zone.name)){const w=children.find(c=>c.dataset.rmBoard==='hadaraWheel');if(w){const decks=children.filter(c=>c.classList.contains('back')&&/10장/.test(c.getAttribute('aria-label')));if(decks.length===5){const box=make('div','rm-hadara-ring');g.prepend(box);box.append(w);decks.forEach((c,i)=>{c.style.setProperty('--angle',(-90+i*72)+'deg');c.style.setProperty('--dx',Math.cos((-90+i*72)*Math.PI/180).toFixed(4));c.style.setProperty('--dy',Math.sin((-90+i*72)*Math.PI/180).toFixed(4));box.append(c);});}}}
 if(id==='euphoria'&&overview&&/공용 구성품/.test(zone.name)){const board=children.find(c=>c.dataset.rmBoard==='city');const markets=children.filter(c=>/^ovmarket/.test(c.dataset.piece||''));if(board&&markets.length===6){const wrap=make('div','rm-city-wrap');g.prepend(wrap);wrap.append(board);markets.forEach((c,i)=>{c.style.setProperty('--mx',(7.8+(i%2)*9.05+Math.floor(i/2)*33.1)+'%');c.style.setProperty('--my','43%');wrap.append(c);});}}
}
function theme(id){document.body.dataset.rmExpanded=id;document.documentElement.style.setProperty('--rm-table-art',`url('${A.wood}')`);}
window.RMExpandedArt={decorate,arrange,theme};})();
